#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, b;
    cin >> n >> b;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    vector<int> diff;
    int even = (a[0] % 2 == 0) ? 1 : 0;
    int odd = (a[0] % 2 == 1) ? 1 : 0;
    for (int i = 1; i < n; i++) {
        if (even == odd) {
            diff.push_back(abs(a[i] - a[i - 1]));
        }
        if (a[i] % 2 == 0) {
            even++;
        } else {
            odd++;
        }
    }
    std::sort(diff.begin(), diff.end());
    long long sum = 0;
    int count = 0;
    for (int i = 0; i < (int)diff.size(); i++) {
        if (diff[i] + sum <= b) {
            count++;
            sum += diff[i];
        }
    }
    cout << count << "\n";
    return 0;
}
